// ==================== ФУНКЦИИ ДЛЯ РАБОТЫ С ДАТАМИ ====================

// Функция для форматирования даты в формат DD.MM.YYYY (получает строку)
function formatDate(dateStr) {
    if (!dateStr) return '';
    try {
        // Если уже отформатированная дата, возвращаем как есть
        if (typeof dateStr === 'string' && dateStr.includes('.')) {
            // Проверяем формат DD.MM.YYYY
            const parts = dateStr.split('.');
            if (parts.length === 3 && parts[0].length === 2 && parts[1].length === 2) {
                return dateStr;
            }
        }
        
        const date = parseDate(dateStr);
        if (!date) return dateStr;
        
        const day = date.getDate().toString().padStart(2, '0');
        const month = (date.getMonth() + 1).toString().padStart(2, '0');
        const year = date.getFullYear();
        
        return `${day}.${month}.${year}`;
    } catch (e) {
        console.warn('Ошибка форматирования даты:', dateStr, e);
        return dateStr;
    }
}

// Функция для парсинга даты из строки в формате DD.MM.YYYY
function parseDate(dateStr) {
    try {
        if (!dateStr) return null;
        
        // Если это уже объект Date, возвращаем его
        if (dateStr instanceof Date) return dateStr;
        
        // Обрабатываем строку
        if (typeof dateStr === 'string') {
            const [day, month, year] = dateStr.split('.').map(Number);
            return new Date(year, month - 1, day);
        }
        
        return null;
    } catch (e) {
        console.warn('Ошибка парсинга даты:', dateStr, e);
        return null;
    }
}

function getWeekStart(date) {
    if (!date) return null;
    
    // Если это строка, парсим ее
    if (typeof date === 'string') {
        date = parseDate(date);
        if (!date) return null;
    }
    
    const day = date.getDay(); // 0-воскресенье, 1-понедельник, ..., 6-суббота
    const diff = date.getDate() - day + (day === 0 ? -6 : 1); // Приводим к понедельнику
    const monday = new Date(date);
    monday.setDate(diff);
    monday.setHours(0, 0, 0, 0);
    return monday;
}

function getWeekEnd(startDate) {
    if (!startDate) return null;
    
    const endDate = new Date(startDate);
    endDate.setDate(endDate.getDate() + 6);
    return endDate;
}

// ==================== ФУНКЦИИ ДЛЯ РАБОТЫ С НЕДЕЛЯМИ ====================

// Функция для извлечения всех уникальных недель из данных
function extractAllWeeksFromData() {
    console.log('=== Извлечение всех недель из данных ===');
    
    const weeksMap = new Map();
    const allWeeksArray = [];
    
    // 1. Обрабатываем pnlData (исключая франшизу роялти)
    if (pnlData && Array.isArray(pnlData)) {
        console.log('Обработка pnlData, записей:', pnlData.length);
        
        pnlData.forEach((entry, index) => {
            const object = entry["Объект"];
            const address = entry["Адрес"];
            
            // ИГНОРИРУЕМ ФРАНШИЗУ РОЯЛТИ
            if (object && 
                (object.toString().toLowerCase().includes('франшиза роялти') || 
                 object.toString().toLowerCase().includes('франшизароялти'))) {
                return;
            }
            
            if (address && 
                (address.toString().toLowerCase().includes('франшиза роялти') || 
                 address.toString().toLowerCase().includes('франшизароялти'))) {
                return;
            }
            
            // Для записей, которые уже имеют поле "Неделя"
            if (entry["Неделя"]) {
                const [startStr] = entry["Неделя"].split(" - ");
                const startDate = parseDate(startStr);
                const weekStart = getWeekStart(startDate);
                if (!weekStart) return;
                
                const weekKey = weekStart.toISOString().split('T')[0];
                
                if (!weeksMap.has(weekKey)) {
                    const weekEnd = getWeekEnd(weekStart);
                    if (!weekEnd) return;
                    
                    weeksMap.set(weekKey, {
                        start: weekStart,
                        startStr: formatDate(weekStart),
                        endStr: formatDate(weekEnd),
                        range: `${formatDate(weekStart)} - ${formatDate(weekEnd)}`,
                        key: weekKey
                    });
                }
            }
            // Для записей с полем "Дата" (дневные данные)
            else if (entry["Дата"]) {
                const date = parseDate(entry["Дата"]);
                const weekStart = getWeekStart(date);
                if (!weekStart) return;
                
                const weekKey = weekStart.toISOString().split('T')[0];
                
                if (!weeksMap.has(weekKey)) {
                    const weekEnd = getWeekEnd(weekStart);
                    if (!weekEnd) return;
                    
                    weeksMap.set(weekKey, {
                        start: weekStart,
                        startStr: formatDate(weekStart),
                        endStr: formatDate(weekEnd),
                        range: `${formatDate(weekStart)} - ${formatDate(weekEnd)}`,
                        key: weekKey
                    });
                }
            }
        });
    }
    
    // 2. Обрабатываем expensesData (но только для добавления недостающих недель)
    if (expensesData && Array.isArray(expensesData)) {
        console.log('Обработка expensesData, записей:', expensesData.length);
        
        expensesData.forEach(entry => {
            if (entry["Дата"]) {
                const date = parseDate(entry["Дата"]);
                const weekStart = getWeekStart(date);
                if (!weekStart) return;
                
                const weekKey = weekStart.toISOString().split('T')[0];
                
                // Добавляем только если недели еще нет в карте
                if (!weeksMap.has(weekKey)) {
                    const weekEnd = getWeekEnd(weekStart);
                    if (!weekEnd) return;
                    
                    weeksMap.set(weekKey, {
                        start: weekStart,
                        startStr: formatDate(weekStart),
                        endStr: formatDate(weekEnd),
                        range: `${formatDate(weekStart)} - ${formatDate(weekEnd)}`,
                        key: weekKey
                    });
                }
            }
        });
    }
    
    // Сортируем недели по дате (от самой ранней к самой поздней)
    const sortedWeeks = Array.from(weeksMap.values())
        .sort((a, b) => a.start - b.start);
    
    // Нумеруем недели начиная с 2
    sortedWeeks.forEach((week, index) => {
        allWeeksArray.push({
            number: index + 2, // Начинаем с номера 2
            range: week.range,
            startDate: week.startStr,
            endDate: week.endStr,
            startDateISO: week.key,
            startObj: week.start
        });
    });
    
    console.log('Найдено недель (без франшизы роялти):', allWeeksArray.length);
    if (allWeeksArray.length > 0) {
        console.log('Первые 5 недель:', allWeeksArray.slice(0, 5));
        console.log('Последние 5 недель:', allWeeksArray.slice(-5));
    }
    
    return allWeeksArray;
}

// Функция для получения номера недели по дате
function getWeekNumberForDate(dateStr) {
    if (!dateStr) return null;
    
    const targetDate = parseDate(dateStr);
    if (!targetDate) return null;
    
    const targetWeekStart = getWeekStart(targetDate);
    if (!targetWeekStart) return null;
    
    const targetWeekKey = targetWeekStart.toISOString().split('T')[0];
    
    // Ищем неделю в списке
    const existingWeek = allWeeks.find(week => 
        week.startDateISO === targetWeekKey
    );
    
    return existingWeek ? existingWeek.number : null;
}

// Функция для получения диапазона недели по номеру
function getWeekRangeByNumber(weekNumber) {
    const week = allWeeks.find(w => w.number === weekNumber);
    return week ? week.range : null;
}

// Функция для заполнения селектора недель
function populateWeekFilter(weeks) {
    const weekSelect = document.getElementById('weekSelect');
    if (!weekSelect) {
        console.error('Элемент weekSelect не найден!');
        return;
    }
    
    weekSelect.innerHTML = '';
    
    // Добавляем опцию "Все недели"
    const allOption = document.createElement('option');
    allOption.value = 'all';
    allOption.textContent = 'Все недели';
    weekSelect.appendChild(allOption);
    
    // Добавляем опции для каждой недели
    weeks.forEach(week => {
        const option = document.createElement('option');
        option.value = week.number;
        option.textContent = `${week.number}н (${week.range})`;
        option.dataset.range = week.range;
        weekSelect.appendChild(option);
    });
    
    // Выбираем все недели по умолчанию
    const options = weekSelect.options;
    for (let i = 0; i < options.length; i++) {
        options[i].selected = true;
    }
    
    updateSelectedInfo('weekSelected', weekSelect);
}

// ==================== ОБРАБОТКА ДАННЫХ ДЛЯ НЕДЕЛЬ ====================

// Функция для обработки данных компании (группировка дневных данных по неделям)
function processCompanyDataForWeeks(data) {
    console.log('=== Обработка данных для работы с неделями ===');
    
    // Извлекаем все недели из данных
    allWeeks = extractAllWeeksFromData();
    
    // Создаем массив для обработанных данных
    const processedData = [];
    
    // Разделяем данные на недельные и дневные
    const weeklyEntries = data.filter(row => row['Неделя'] && !row['Дата']);
    const dailyEntries = data.filter(row => row['Дата'] && !row['Неделя']);
    
    console.log('Недельных записей (готовых):', weeklyEntries.length);
    console.log('Дневных записей (для группировки):', dailyEntries.length);
    
    // 1. Обрабатываем уже готовые недельные данные (ИСКЛЮЧАЕМ ФРАНШИЗУ РОЯЛТИ)
    weeklyEntries.forEach(row => {
        const object = row['Объект'];
        const address = row['Адрес'];
        
        // ИГНОРИРУЕМ ФРАНШИЗУ РОЯЛТИ
        if (object && 
            (object.toString().toLowerCase().includes('франшиза роялти') || 
             object.toString().toLowerCase().includes('франшизароялти'))) {
            console.log('Пропускаем недельную запись с франшизой роялти:', { object, address });
            return;
        }
        
        // Также проверяем адрес на наличие франшизы роялти
        if (address && 
            (address.toString().toLowerCase().includes('франшиза роялти') || 
             address.toString().toLowerCase().includes('франшизароялти'))) {
            console.log('Пропускаем недельную запись с франшизой роялти по адресу:', { object, address });
            return;
        }
        
        const processedRow = {};
        
        // Определяем номер недели
        if (row['Неделя']) {
            const [startStr] = row['Неделя'].split(" - ");
            const weekNumber = getWeekNumberForDate(startStr);
            
            if (weekNumber) {
                processedRow['Неделя'] = row['Неделя'];
                processedRow['Номер недели'] = weekNumber;
            }
        }
        
        // Копируем остальные поля
        for (const key in row) {
            if (key !== 'Неделя' && key !== 'Дата') {
                if (key === 'Объект' || key === 'Адрес') {
                    processedRow[key] = row[key];
                } else {
                    let value = row[key];
                    if (typeof value === 'string') {
                        value = value.replace(/\s/g, '').replace(',', '.');
                        value = value.replace(/[^\d.-]/g, '');
                    }
                    processedRow[key] = parseFloat(value) || 0;
                }
            }
        }
        
        processedData.push(processedRow);
    });
    
    // 2. Группируем дневные данные по неделям (ИСКЛЮЧАЕМ ФРАНШИЗУ РОЯЛТИ)
    const groupedDailyData = groupDailyDataByWeek(dailyEntries);
    
    // 3. Объединяем данные
    const allProcessedData = [...processedData, ...groupedDailyData];
    
    // Сохраняем все столбцы
    if (allProcessedData.length > 0) {
        allColumns = Object.keys(allProcessedData[0]);
    }
    
    console.log('Всего обработано записей:', allProcessedData.length);
    
    return allProcessedData;
}

// Функция для группировки дневных данных по неделям
function groupDailyDataByWeek(dailyEntries) {
    console.log('=== Группировка дневных данных по неделям ===');
    
    const weeklyMap = new Map();
    
    dailyEntries.forEach(entry => {
        const dateStr = entry['Дата'];
        if (!dateStr) return;
        
        const object = entry['Объект'];
        const address = entry['Адрес'];
        
        // ИГНОРИРУЕМ ФРАНШИЗУ РОЯЛТИ
        if (object && 
            (object.toString().toLowerCase().includes('франшиза роялти') || 
             object.toString().toLowerCase().includes('франшизароялти'))) {
            return;
        }
        
        // Также проверяем адрес на наличие франшизы роялти
        if (address && 
            (address.toString().toLowerCase().includes('франшиза роялти') || 
             address.toString().toLowerCase().includes('франшизароялти'))) {
            return;
        }
        
        const weekNumber = getWeekNumberForDate(dateStr);
        if (!weekNumber) return;
        
        const weekRange = getWeekRangeByNumber(weekNumber);
        if (!weekRange) return;
        
        // Создаем уникальный ключ для группировки
        const key = `${weekNumber}_${object}_${address}`;
        
        if (!weeklyMap.has(key)) {
            // Создаем новую недельную запись
            weeklyMap.set(key, {
                'Неделя': weekRange,
                'Номер недели': weekNumber,
                'Объект': object,
                'Адрес': address
            });
            
            // Инициализируем все числовые поля
            Object.keys(entry).forEach(field => {
                if (field !== 'Дата' && field !== 'Неделя' && 
                    field !== 'Объект' && field !== 'Адрес') {
                    weeklyMap.get(key)[field] = 0;
                }
            });
        }
        
        // Суммируем значения
        const weeklyEntry = weeklyMap.get(key);
        Object.keys(entry).forEach(field => {
            if (field !== 'Дата' && field !== 'Неделя' && 
                field !== 'Объект' && field !== 'Адрес') {
                const value = parseFloat(entry[field]) || 0;
                weeklyEntry[field] = (parseFloat(weeklyEntry[field]) || 0) + value;
            }
        });
    });
    
    // Преобразуем Map в массив
    const groupedData = Array.from(weeklyMap.values());
    
    console.log('Сгруппировано недельных записей:', groupedData.length);
    
    return groupedData;
}

// ==================== ФУНКЦИИ ДЛЯ ФОРМАТИРОВАНИЯ ====================

function formatCurrency(value) {
    if (value === 0) return '0';
    const absValue = Math.abs(value);
    if (absValue >= 1000000) {
        return (value / 1000000).toFixed(1) + 'M';
    } else if (absValue >= 1000) {
        return (value / 1000).toFixed(0) + 'k';
    }
    return Math.round(value).toLocaleString('ru-RU', { minimumFractionDigits: 0, maximumFractionDigits: 0 });
}

function formatNumber(value) {
    if (value === 0 || value === '0') return '0';
    if (typeof value === 'string') {
        const num = parseFloat(value.replace(',', '.'));
        if (isNaN(num)) return value;
        value = num;
    }
    return value.toLocaleString('ru-RU', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// ==================== РАБОТА С РАСХОДАМИ ====================

function loadCompanyExpensesData(data) {
    companyExpensesData = [];

    data.forEach(row => {
        const date = row['Дата'];
        if (date) {
            // Упрощенная версия - просто используем дату как есть
            const formattedDate = date; // Не форматируем, т.к. уже в правильном формате
            const generalExpense = parseFloat(String(row['Общий расход']).replace(',', '.')) || 0;
            const salaryExpense = parseFloat(String(row['З/п офис']).replace(',', '.')) || 0;

            companyExpensesData.push({
                дата: formattedDate,
                общий_расход: generalExpense,
                зп_офис: salaryExpense
            });
        }
    });

    console.log('Загружены данные о расходах компании:', companyExpensesData.length, 'записей');
    companyExpensesFileLoaded = true;
}

// ==================== АГРЕГАЦИЯ ДАННЫХ ПО НЕДЕЛЯМ ====================

function aggregateWeeklyData(data, selectedWeeks = null, selectedObjects = null, selectedAddresses = null) {
    console.log('=== Агрегация данных по неделям ===');
    
    const weeklyAggregated = {};

    const isAllObjects = !selectedObjects || selectedObjects.length === 0;
    const isAllAddresses = !selectedAddresses || selectedAddresses.length === 0;
    const shouldIncludeCompanyExpenses = isAllObjects && isAllAddresses && companyExpensesFileLoaded;
    
    // Проверяем, выбран ли объект "Франшиза отдел сопровождения"
    const isFranchiseSupportSelected = selectedObjects && 
        selectedObjects.some(obj => 
            obj && 
            (obj.toString().toLowerCase().includes('франшиза отдел сопровождения') ||
             obj.toString().toLowerCase().includes('франшиза сопровождение'))
        );
    
    // Включаем франшизу бонус если выбраны все объекты и все адреса, ИЛИ выбран объект франшизы
    const shouldIncludeFranchiseBonus = (isAllObjects && isAllAddresses) || isFranchiseSupportSelected;

    data.forEach(row => {
        const weekNumber = row['Номер недели'];
        const weekRange = row['Неделя'];
        const object = row['Объект'];
        const address = row['Адрес'];

        if (!weekNumber || !weekRange) return;
        
        // ИГНОРИРУЕМ ФРАНШИЗУ РОЯЛТИ (дополнительная проверка)
        if (object && 
            (object.toString().toLowerCase().includes('франшиза роялти') || 
             object.toString().toLowerCase().includes('франшизароялти'))) {
            return;
        }
        
        if (address && 
            (address.toString().toLowerCase().includes('франшиза роялти') || 
             address.toString().toLowerCase().includes('франшизароялти'))) {
            return;
        }

        // Проверяем, выбрана ли неделя
        if (selectedWeeks && selectedWeeks.length > 0) {
            if (!selectedWeeks.includes(weekNumber)) return;
        }

        // Фильтрация по объектам
        if (selectedObjects && selectedObjects.length > 0) {
            let objectMatch = false;
            
            if (selectedObjects.includes('all_retail')) {
                objectMatch = retailObjects.includes(object);
            } else {
                objectMatch = selectedObjects.includes(object);
            }
            
            if (!objectMatch) return;
        }

        // Фильтрация по адресам
        if (selectedAddresses && selectedAddresses.length > 0) {
            if (!selectedAddresses.includes(address)) return;
        }

        if (!weeklyAggregated[weekNumber]) {
            weeklyAggregated[weekNumber] = {
                weekNumber: weekNumber,
                weekRange: weekRange,
                revenue: 0,
                operatingProfit: 0,
                autoChemistry: 0,
                utilities: 0,
                rent: 0,
                salary: 0,
                commissions: 0,
                taxes: 0,
                vat: 0,
                other: 0,
                indivisibleExpense: 0,
                franchiseBonus: 0,
                generalExpense: 0,
                salaryOfficeExpense: 0,
                adjustedOperatingProfit: 0,
                rawData: {}
            };
        }

        const weekData = weeklyAggregated[weekNumber];

        // Суммируем данные
        weekData.revenue += (row['Выручка'] || 0) + (row['Выручка Сайт'] || 0);

        // Включаем франшиза бонус только если нужно
        if (shouldIncludeFranchiseBonus) {
            const franchiseBonus = row['Франшиза сопровождение бонус'] || 0;
            weekData.revenue += franchiseBonus;
            weekData.franchiseBonus += franchiseBonus;
        }

        weekData.operatingProfit += row['Операционная прибыль'] || 0;

        weekData.autoChemistry +=
            (row['Автохимия Шампунь Москва'] || 0) +
            (row['Автохимия Шампунь СПБ'] || 0) +
            (row['Автохимия Пена'] || 0) +
            (row['Автохимия Юр. Лица'] || 0) +
            (row['Автохимия Абонементы/сертификаты/подписки'] || 0);

        weekData.utilities +=
            (row['Коммунальные расходы'] || 0) +
            (row['Коммунальные расходы Абонементы/сертификаты/подписки'] || 0);

        weekData.rent += row['Аренда'] || 0;
        weekData.salary += row['Зарплата'] || 0;
        weekData.commissions += row['Комиссии'] || 0;
        weekData.taxes += row['Налоги'] || 0;
        weekData.vat += row['НДС'] || 0;
        weekData.other += row['Прочие'] || 0;
        weekData.indivisibleExpense += row['Неделимый расход'] || 0;

        // Сохраняем сырые данные
        for (const key in row) {
            if (key !== 'Неделя' && key !== 'Номер недели' && 
                key !== 'Объект' && key !== 'Адрес' &&
                typeof row[key] === 'number') {
                if (!weekData.rawData[key]) weekData.rawData[key] = 0;
                weekData.rawData[key] += row[key];
            }
        }
    });

    // Добавляем расходы компании для каждой недели
    if (shouldIncludeCompanyExpenses) {
        // Группируем расходы по неделям
        const weeklyExpenses = {};
        
        companyExpensesData.forEach(expense => {
            const weekNumber = getWeekNumberForDate(expense.дата);
            if (!weekNumber) return;
            
            if (!weeklyExpenses[weekNumber]) {
                weeklyExpenses[weekNumber] = {
                    generalExpense: 0,
                    salaryExpense: 0
                };
            }
            
            weeklyExpenses[weekNumber].generalExpense += expense.общий_расход || 0;
            weeklyExpenses[weekNumber].salaryExpense += expense.зп_офис || 0;
        });

        // Применяем расходы к соответствующим неделям
        Object.keys(weeklyAggregated).forEach(weekNum => {
            const weekNumber = parseInt(weekNum);
            if (weeklyExpenses[weekNumber]) {
                weeklyAggregated[weekNumber].generalExpense = weeklyExpenses[weekNumber].generalExpense;
                weeklyAggregated[weekNumber].salaryOfficeExpense = weeklyExpenses[weekNumber].salaryExpense;
                
                weeklyAggregated[weekNumber].adjustedOperatingProfit =
                    weeklyAggregated[weekNumber].operatingProfit +
                    weeklyAggregated[weekNumber].generalExpense +
                    weeklyAggregated[weekNumber].salaryOfficeExpense;
            } else {
                weeklyAggregated[weekNumber].adjustedOperatingProfit = weeklyAggregated[weekNumber].operatingProfit;
            }
        });
    } else {
        Object.keys(weeklyAggregated).forEach(weekNumber => {
            weeklyAggregated[weekNumber].adjustedOperatingProfit = weeklyAggregated[weekNumber].operatingProfit;
        });
    }

    // Преобразуем объект в массив и сортируем по номеру недели
    const result = Object.values(weeklyAggregated);
    result.sort((a, b) => a.weekNumber - b.weekNumber);

    console.log('Агрегировано недель (без франшизы роялти):', result.length);
    console.log('shouldIncludeFranchiseBonus:', shouldIncludeFranchiseBonus, 
                'isFranchiseSupportSelected:', isFranchiseSupportSelected);
    return result;
}

// Функция для обновления фильтра адресов при выборе объекта (для недельной версии)
function updateAddressFilterForWeeks(selectedObject, data) {
    const addressSelect = document.getElementById('addressSelect');
    if (!addressSelect) return;
    
    const currentSelected = Array.from(addressSelect.selectedOptions).map(opt => opt.value);
    
    console.log('=== updateAddressFilterForWeeks ===');
    console.log('selectedObject:', selectedObject);
    console.log('Текущие выбранные адреса:', currentSelected);
    
    let filteredAddresses;
    
    if (selectedObject === 'all_retail') {
        // Для "Вся розница" показываем адреса в заданном порядке из HTML
        const retailAddressesOrder = [
            "ДМИТРОВСКОЕ",
            "ПЯТНИЦКОЕ",
            "Пятницкое шоссе 20",
            "ХИМКИ",
            "ШЕРЕМЕТЬЕВСКАЯ",
            "МИЧУРИНСКИЙ",
            "ЛОБАЧЕВСКОГО 37",
            "ЛОБАЧЕВСКОГО 92",
            "ЛОБАЧЕВСКОГО 19",
            "РУБЛЕВКА91",
            "РУБЛЕВСКОЕ вл.4",
            "Минская",
            "ПРАВОБЕРЕЖНАЯ",
            "Носовихинское",
            "Пр Мира 94 А",
            "ТТК",
            "МЫТИЩИ",
            "ПЛЕЩЕЕВА",
            "ВЕРНАДСКОГО",
            "НОВОЯСЕНЕВСКИЙ",
            "ПРОФСОЮЗНАЯ",
            "Дзержинский, Угрешская",
            "ЗАГОРОДНОЕ",
            "ПРИВОЛЬНАЯ",
            "ЛЮБЛИНСКАЯ 135",
            "Каспийская",
            "КАШИРСКОЕ 24",
            "Коломенский пр-д",
            "ВДНХ",
            "Куликовская",
            "Чертановская",
            "СПб, Маршала Жукова",
            "ПАПЕРНИКА вл.22",
            "СЕРПУХОВ",
            "ПРИШВИНА"
        ];
        
        // Фильтруем адреса из порядка, которые реально существуют в данных
        filteredAddresses = retailAddressesOrder.filter(address => {
            // Проверяем, есть ли этот адрес в данных
            return data.some(row => {
                const rowAddress = row['Адрес'];
                if (!rowAddress) return false;
                
                // Сначала проверяем точное совпадение
                if (rowAddress === address) return true;
                
                // Проверяем без учета регистра
                if (rowAddress.toLowerCase() === address.toLowerCase()) return true;
                
                return false;
            });
        });
        
        console.log('Адреса для "Вся розница" (в заданном порядке):', filteredAddresses.length);
    } else if (selectedObject && selectedObject !== '') {
        // Адреса для конкретного объекта
        filteredAddresses = [...new Set(data
            .filter(row => row['Объект'] === selectedObject)
            .map(row => row['Адрес']))].filter(Boolean);
            
        // Фильтруем адреса, исключая франшизу роялти
        filteredAddresses = filteredAddresses.filter(address => {
            const addr = String(address).toLowerCase().trim();
            return !addr.includes('франшиза роялти') && !addr.includes('франшизароялti');
        });
        
        // Сортируем адреса для конкретного объекта
        filteredAddresses.sort((a, b) => a.localeCompare(b));
    } else {
        // Все адреса (исключая франшизу роялти)
        const allAddresses = [...new Set(data.map(row => row['Адрес']))].filter(Boolean);
        filteredAddresses = allAddresses.filter(address => {
            const addr = String(address).toLowerCase().trim();
            return !addr.includes('франшиза роялти') && !addr.includes('франшизароялti');
        });
        
        // Сохраняем существующий порядок из HTML для "Все объекты"
        const htmlOptions = Array.from(addressSelect.options)
            .map(opt => opt.value)
            .filter(value => value && value !== '');
        
        // Оставляем только те адреса, которые есть в данных
        filteredAddresses = htmlOptions.filter(addr => 
            allAddresses.some(dataAddr => {
                if (dataAddr === addr) return true;
                if (dataAddr.toLowerCase() === addr.toLowerCase()) return true;
                return false;
            })
        );
        
        // Добавляем адреса из данных, которых нет в HTML
        const missingAddresses = allAddresses.filter(addr => 
            !filteredAddresses.some(htmlAddr => 
                htmlAddr === addr || htmlAddr.toLowerCase() === addr.toLowerCase()
            )
        );
        
        filteredAddresses = [...filteredAddresses, ...missingAddresses];
    }
    
    console.log('Доступные адреса для выбора:', filteredAddresses.length);
    
    addressSelect.innerHTML = '<option value="">Все адреса</option>';
    
    filteredAddresses.forEach(address => {
        const option = document.createElement('option');
        option.value = address;
        option.textContent = address;
        
        // Сохраняем выбранные ранее адреса, если они есть в новом списке
        if (currentSelected.includes(address)) {
            option.selected = true;
        }
        
        addressSelect.appendChild(option);
    });
    
    updateSelectedInfo('addressSelected', addressSelect);
}

// ==================== ФИЛЬТРЫ И ИНТЕРФЕЙС ====================

function populateFiltersForWeeks(data) {
    console.log('=== populateFiltersForWeeks ===');
    
    // Получаем объекты и адреса (ИСКЛЮЧАЕМ ФРАНШИЗУ РОЯЛТИ)
    const objects = [...new Set(data.map(row => row['Объект']))]
        .filter(Boolean)
        .filter(obj => {
            const objStr = String(obj).toLowerCase();
            return !objStr.includes('франшиза роялти') && 
                   !objStr.includes('франшизароялти') &&
                   obj !== "Продажа объекта/агентские";
        });

    // Настраиваем фильтр объектов
    const objectSelect = document.getElementById('objectSelect');
    if (!objectSelect) {
        console.error('Элемент objectSelect не найден!');
        return;
    }
    
    // Если объекты уже заданы в HTML в правильном порядке, не перезаписываем их
    // Просто добавляем только те объекты из данных, которых еще нет в списке
    const existingObjects = Array.from(objectSelect.options)
        .map(opt => opt.value)
        .filter(value => value && value !== '' && value !== 'all_retail');
    
    console.log('Существующие объекты в HTML:', existingObjects);
    console.log('Объекты из данных:', objects);
    
    // Добавляем только те объекты из данных, которых еще нет в списке
    objects.forEach(obj => {
        if (!existingObjects.includes(obj)) {
            const option = document.createElement('option');
            option.value = obj;
            option.textContent = obj;
            objectSelect.appendChild(option);
        }
    });

    // Получаем адреса (ИСКЛЮЧАЕМ ФРАНШИЗУ РОЯЛТИ)
    const addressesFromData = [...new Set(data.map(row => row['Адрес']))]
        .filter(Boolean)
        .filter(addr => {
            const addrStr = String(addr).toLowerCase();
            return !addrStr.includes('франшиза роялти') && 
                   !addrStr.includes('франшизароялti');
        });

    // Настраиваем фильтр адресов
    const addressSelect = document.getElementById('addressSelect');
    if (!addressSelect) {
        console.error('Элемент addressSelect не найден!');
        return;
    }
    
    // Если адреса уже заданы в HTML (в нужном порядке для "Вся розница"), не перезаписываем их
    // Просто добавляем динамически найденные адреса, которых еще нет
    const existingAddresses = Array.from(addressSelect.options)
        .map(opt => opt.value)
        .filter(value => value && value !== '');
    
    console.log('Существующие адреса в HTML:', existingAddresses.length);
    console.log('Адреса из данных (после фильтрации):', addressesFromData.length);
    
    // Добавляем только те адреса, которых еще нет в списке
    addressesFromData.forEach(address => {
        if (!existingAddresses.includes(address)) {
            const option = document.createElement('option');
            option.value = address;
            option.textContent = address;
            addressSelect.appendChild(option);
        }
    });

    // Настраиваем фильтр недель
    populateWeekFilter(allWeeks);

    // Показываем фильтры
    const filtersElement = document.getElementById('filters');
    if (filtersElement) {
        filtersElement.style.display = 'flex';
    }

    // Добавляем обработчики событий
    const weekSelect = document.getElementById('weekSelect');
    if (weekSelect) {
        weekSelect.addEventListener('change', function () {
            updateSelectedInfo('weekSelected', this);
            applyFiltersForWeeks();
        });
    }

    objectSelect.addEventListener('change', function () {
        updateSelectedInfo('objectSelected', this);
        updateAddressFilterForWeeks(this.value, data);
        applyFiltersForWeeks();
    });

    addressSelect.addEventListener('change', function () {
        updateSelectedInfo('addressSelected', this);
        applyFiltersForWeeks();
    });

    updateSelectedInfo('objectSelected', objectSelect);
    updateSelectedInfo('addressSelected', addressSelect);
    updateSelectedInfo('weekSelected', weekSelect);
    
    applyFiltersForWeeks();
}

// Функция для обновления списка адресов при выборе объекта
function updateAddressFilter(selectedObject, data) {
    const addressSelect = document.getElementById('addressSelect');
    if (!addressSelect) return;
    
    const currentSelected = Array.from(addressSelect.selectedOptions).map(opt => opt.value);
    
    let filteredAddresses;
    
    if (selectedObject === 'all_retail') {
        // Все адреса для розничных объектов
        filteredAddresses = [...new Set(data
            .filter(row => retailObjects.includes(row['Объект']))
            .map(row => row['Адрес']))].filter(Boolean);
    } else if (selectedObject && selectedObject !== 'all') {
        // Адреса для конкретного объекта
        filteredAddresses = [...new Set(data
            .filter(row => row['Объект'] === selectedObject)
            .map(row => row['Адрес']))].filter(Boolean);
    } else {
        // Все адреса
        filteredAddresses = [...new Set(data.map(row => row['Адрес']))].filter(Boolean);
    }
    
    // ИСКЛЮЧАЕМ ФРАНШИЗУ РОЯЛТИ
    filteredAddresses = filteredAddresses.filter(address => {
        const addr = String(address).toLowerCase().trim();
        return !addr.includes('франшиза роялти') && !addr.includes('франшизароялти');
    });
    
    // Сортируем адреса
    filteredAddresses.sort((a, b) => a.localeCompare(b));
    
    addressSelect.innerHTML = '<option value="">Все адреса</option>';
    
    filteredAddresses.forEach(address => {
        const option = document.createElement('option');
        option.value = address;
        option.textContent = address;
        
        // Сохраняем выбранные ранее адреса, если они есть в новом списке
        if (currentSelected.includes(address)) {
            option.selected = true;
        }
        
        addressSelect.appendChild(option);
    });
    
    updateSelectedInfo('addressSelected', addressSelect);
}

function updateSelectedInfo(containerId, selectElement) {
    const container = document.getElementById(containerId);
    if (!container || !selectElement) return;
    
    const selectedOptions = Array.from(selectElement.selectedOptions)
        .map(option => option.value)
        .filter(value => value && value !== '');

    if (selectElement.id === 'weekSelect') {
        if (selectedOptions.length === 0 || selectedOptions.includes('all')) {
            container.textContent = 'Все недели';
        } else if (selectedOptions.length === 1) {
            const weekNumber = selectedOptions[0];
            const weekOption = selectElement.querySelector(`option[value="${weekNumber}"]`);
            container.textContent = weekOption ? weekOption.textContent : `Неделя ${weekNumber}`;
        } else {
            container.textContent = `Выбрано недель: ${selectedOptions.length}`;
        }
        container.title = selectedOptions.join(', ');
    } else if (selectElement.id === 'objectSelect') {
        if (selectedOptions.length > 0) {
            if (selectedOptions.includes('all_retail')) {
                container.textContent = 'Вся розница';
            } else {
                container.textContent = `Выбрано: ${selectedOptions.length}`;
            }
            container.title = selectedOptions.join(', ');
        } else {
            container.textContent = 'Все';
            container.title = '';
        }
    } else if (selectElement.id === 'addressSelect') {
        if (selectedOptions.length > 0) {
            container.textContent = `Выбрано: ${selectedOptions.length}`;
            container.title = selectedOptions.join(', ');
        } else {
            container.textContent = 'Все';
            container.title = '';
        }
    }
}

function getSelectedWeeks() {
    const weekSelect = document.getElementById('weekSelect');
    if (!weekSelect) return null;
    
    const selectedWeeks = Array.from(weekSelect.selectedOptions)
        .map(option => option.value)
        .filter(value => value && value !== 'all')
        .map(value => parseInt(value));

    return selectedWeeks.length > 0 ? selectedWeeks : null;
}

function getSelectedObjects() {
    const objectSelect = document.getElementById('objectSelect');
    if (!objectSelect) return null;
    
    const selectedObjects = Array.from(objectSelect.selectedOptions)
        .map(option => option.value)
        .filter(value => value && value !== '');

    return selectedObjects.length > 0 ? selectedObjects : null;
}

function getSelectedAddresses() {
    const addressSelect = document.getElementById('addressSelect');
    if (!addressSelect) return null;
    
    const selectedAddresses = Array.from(addressSelect.selectedOptions)
        .map(option => option.value)
        .filter(value => value && value !== '');

    return selectedAddresses.length > 0 ? selectedAddresses : null;
}

function applyFiltersForWeeks() {
    console.log('=== Применение фильтров для недель ===');
    
    const selectedWeeks = getSelectedWeeks();
    const selectedObjects = getSelectedObjects();
    const selectedAddresses = getSelectedAddresses();

    const dataToDisplay = aggregateWeeklyData(companyData, selectedWeeks, selectedObjects, selectedAddresses);
    
    let infoText = `Показано недель: ${dataToDisplay.length}`;
    if (selectedWeeks) {
        infoText += ` | Выбрано недель: ${selectedWeeks.length}`;
    }

    const isAllObjectsFlag = !selectedObjects || selectedObjects.length === 0;
    const isAllAddressesFlag = !selectedAddresses || selectedAddresses.length === 0;
    
    // Проверяем, выбран ли объект "Франшиза отдел сопровождения"
    const isFranchiseSupportSelected = selectedObjects && 
        selectedObjects.some(obj => 
            obj && 
            (obj.toString().toLowerCase().includes('франшиза отдел сопровождения') ||
             obj.toString().toLowerCase().includes('франшиза сопровождение'))
        );

    if (isAllObjectsFlag && isAllAddressesFlag && companyExpensesFileLoaded) {
        infoText += ' | Учтены: Общий расход, З/п офис';
    }

    // Обновляем эту часть:
    const shouldShowFranchiseBonus = (isAllObjectsFlag && isAllAddressesFlag) || isFranchiseSupportSelected;
    if (shouldShowFranchiseBonus) {
        infoText += ' | Учтен: Франшиза сопровождение бонус';
    }

    const companyFileInfo = document.getElementById('companyFileInfo');
    if (companyFileInfo) {
        companyFileInfo.textContent = infoText;
    }

    const chartContainer = document.getElementById('companyChart');
    if (dataToDisplay.length > 0) {
        buildChartForWeeks(dataToDisplay, selectedObjects, selectedAddresses);
    } else {
        if (chartContainer) {
            chartContainer.innerHTML = '<div class="loading">Нет данных для выбранных фильтров</div>';
        }
        
        const statsInfo = document.getElementById('statsInfo');
        if (statsInfo) {
            statsInfo.innerHTML = '';
        }
    }
}

// ==================== ГРАФИК ДЛЯ НЕДЕЛЬ ====================

function buildChartForWeeks(data, selectedObjects, selectedAddresses) {
    const chartContainer = document.getElementById('companyChart');
    if (!chartContainer) return;
    
    chartContainer.innerHTML = '';

    try {
        if (currentCompanyChart && !currentCompanyChart.isDisposed()) {
            currentCompanyChart.dispose();
        }
    } catch (e) {
        console.warn('Ошибка при удалении графика:', e);
    }

    if (!data || data.length === 0) {
        chartContainer.innerHTML = '<div class="loading">Нет данных для отображения</div>';
        return;
    }

    const chart = echarts.init(chartContainer);
    currentCompanyChart = chart;

    const labels = data.map(item => `${item.weekNumber}н`);
    const revenueData = [];
    const positiveProfitData = [];
    const negativeProfitData = [];
    const profitabilityData = [];
    const franchiseBonusData = [];

    data.forEach(item => {
        revenueData.push(item.revenue);

        const profit = item.adjustedOperatingProfit;
        if (profit > 0) {
            positiveProfitData.push(profit);
            negativeProfitData.push(0);
        } else if (profit < 0) {
            positiveProfitData.push(0);
            negativeProfitData.push(profit);
        } else {
            positiveProfitData.push(0);
            negativeProfitData.push(0);
        }

        const profitability = item.revenue !== 0 ? (profit / item.revenue) * 100 : -100;
        profitabilityData.push(profitability);

        franchiseBonusData.push(item.franchiseBonus || 0);
    });

    const emphasisStyle = {
        itemStyle: {
            shadowBlur: 10,
            shadowColor: 'rgba(0,0,0,0.3)'
        }
    };

    const totalRevenue = data.reduce((sum, item) => sum + item.revenue, 0);
    const totalProfit = data.reduce((sum, item) => sum + item.adjustedOperatingProfit, 0);
    const avgProfitability = totalRevenue !== 0 ? (totalProfit / totalRevenue) * 100 : -100;
    const totalFranchiseBonus = data.reduce((sum, item) => sum + (item.franchiseBonus || 0), 0);

    let titleText = 'Финансовые показатели по всей компании (по неделям)';
    let subtitle = `Рентабельность: ${avgProfitability.toFixed(1)}%`;

    if (selectedObjects) {
        if (selectedObjects.includes('all_retail')) {
            subtitle += ` | Объект: Вся розница`;
        } else {
            subtitle += ` | Объектов: ${selectedObjects.length}`;
        }
    }
    if (selectedAddresses) {
        subtitle += ` | Адресов: ${selectedAddresses.length}`;
    }

    const isAllObjectsFlag = !selectedObjects || selectedObjects.length === 0;
    const isAllAddressesFlag = !selectedAddresses || selectedAddresses.length === 0;
    
    // Определяем, нужно ли показывать франшиза бонус
    const isFranchiseSupportSelected = selectedObjects && 
        selectedObjects.some(obj => 
            obj && 
            (obj.toString().toLowerCase().includes('франшиза отдел сопровождения') ||
             obj.toString().toLowerCase().includes('франшиза сопровождение'))
        );
    
    const shouldShowFranchiseBonus = (isAllObjectsFlag && isAllAddressesFlag) || isFranchiseSupportSelected;

    if (isAllObjectsFlag && isAllAddressesFlag && companyExpensesFileLoaded) {
        subtitle += ' | Учтены: Общий расход, З/п офис';
    }

    if (shouldShowFranchiseBonus) {
        subtitle += ' | Учтен: Франшиза сопровождение бонус';
    }

    const option = {
        title: {
            text: titleText,
            subtext: subtitle,
            left: 'center',
            textStyle: {
                fontSize: 16,
                fontWeight: 'bold'
            }
        },
        legend: {
            data: ['Прибыль (+)', 'Прибыль (-)', 'Выручка'],
            left: '10%',
            top: 50,
        },
        tooltip: {
            trigger: 'axis',
            axisPointer: {
                type: 'shadow'
            },
            formatter: function (params) {
                let result = `<div style="text-align: left">`;
                const index = params[0].dataIndex;
                const item = data[index];
                
                result += `<strong>${item.weekNumber}н (${item.weekRange})</strong><br/>`;

                params.forEach(param => {
                    if (param.value !== 0) {
                        const value = formatCurrency(param.value);
                        const seriesName = param.seriesName;
                        result += `${seriesName}: ${value}<br/>`;
                    }
                });

                const bonus = franchiseBonusData[index];
                if (shouldShowFranchiseBonus && bonus !== 0) {
                    result += `<span style="color: #28a745;">Франшиза сопровождение бонус: ${formatCurrency(bonus)}</span><br/>`;
                }

                const profitability = profitabilityData[index];
                const profitColor = profitability >= 0 ? '#28a745' : '#dc3545';
                result += `<span style="color: ${profitColor}; font-weight: bold;">Рентабельность: ${profitability.toFixed(1)}%</span>`;

                result += `</div>`;
                return result;
            }
        },
        toolbox: {
            feature: {
                magicType: {
                    type: ['stack']
                },
                dataView: {
                    show: true,
                    readOnly: true,
                    title: 'Данные по неделям',
                    lang: ['Таблица данных', 'Закрыть', 'Обновить'],
                    optionToContent: function (opt) {
                        const table = document.createElement('div');
                        table.style.width = '100%';
                        table.style.maxHeight = '500px';
                        table.style.overflow = 'auto';

                        const tableContent = document.createElement('table');
                        tableContent.className = 'data-view-table';

                        const thead = document.createElement('thead');
                        const headerRow = document.createElement('tr');

                        const weekHeader = document.createElement('th');
                        weekHeader.textContent = 'Неделя';
                        weekHeader.style.textAlign = 'center';
                        weekHeader.style.position = 'sticky';
                        weekHeader.style.left = '0';
                        weekHeader.style.zIndex = '20';
                        weekHeader.style.backgroundColor = '#f2f2f2';
                        headerRow.appendChild(weekHeader);

                        allColumns.forEach(column => {
                            if (column !== 'Неделя' && column !== 'Номер недели' && 
                                column !== 'Объект' && column !== 'Адрес') {
                                const th = document.createElement('th');
                                th.textContent = column;
                                th.style.textAlign = 'center';
                                headerRow.appendChild(th);
                            }
                        });

                        thead.appendChild(headerRow);
                        tableContent.appendChild(thead);

                        const tbody = document.createElement('tbody');

                        data.forEach(item => {
                            const row = document.createElement('tr');

                            const weekCell = document.createElement('td');
                            weekCell.textContent = `${item.weekNumber}н (${item.weekRange})`;
                            weekCell.style.textAlign = 'center';
                            weekCell.style.position = 'sticky';
                            weekCell.style.left = '0';
                            weekCell.style.zIndex = '10';
                            weekCell.style.backgroundColor = 'white';
                            row.appendChild(weekCell);

                            allColumns.forEach(column => {
                                if (column !== 'Неделя' && column !== 'Номер недели' && 
                                    column !== 'Объект' && column !== 'Адрес') {
                                    const td = document.createElement('td');
                                    let value = 0;

                                    if (item.rawData && item.rawData[column] !== undefined) {
                                        value = item.rawData[column];
                                    }

                                    td.textContent = formatNumber(value);
                                    row.appendChild(td);
                                }
                            });

                            tbody.appendChild(row);
                        });

                        tableContent.appendChild(tbody);
                        table.appendChild(tableContent);

                        return table;
                    },
                    contentToOption: function () {
                        return null;
                    }
                },
                saveAsImage: {
                    title: 'Сохранить',
                    pixelRatio: 2
                }
            },
            right: 20,
            top: 50
        },
        xAxis: {
            type: 'category',
            data: labels,
            axisLine: { onZero: true },
            splitLine: { show: false },
            splitArea: { show: false },
            axisLabel: {
                interval: 0,
                rotate: 0
            }
        },
        yAxis: {
            show: true,
            type: 'value',
            name: 'Сумма',
            axisLabel: {
                formatter: formatCurrency
            }
        },
        grid: {
            left: '3%',
            right: '4%',
            bottom: '15%',
            top: 100,
            containLabel: true
        },
        series: [
            {
                name: 'Прибыль (+)',
                type: 'bar',
                stack: 'profit',
                emphasis: emphasisStyle,
                itemStyle: {
                    color: '#FF9800'
                },
                label: {
                    show: true,
                    position: 'inside',
                    formatter: function (params) {
                        return params.value !== 0 ? formatCurrency(params.value) : '';
                    },
                    fontSize: 10,
                    fontWeight: 'bold',
                    color: '#ffffff'
                },
                data: positiveProfitData
            },
            {
                name: 'Прибыль (-)',
                type: 'bar',
                stack: 'profit',
                emphasis: emphasisStyle,
                itemStyle: {
                    color: '#FF9800'
                },
                label: {
                    show: true,
                    position: 'inside',
                    formatter: function (params) {
                        return params.value !== 0 ? formatCurrency(params.value) : '';
                    },
                    fontSize: 10,
                    fontWeight: 'bold',
                    color: '#F44336'
                },
                data: negativeProfitData
            },
            {
                name: 'Выручка',
                type: 'bar',
                emphasis: emphasisStyle,
                itemStyle: {
                    color: '#FFE0B2'
                },
                label: {
                    show: true,
                    position: 'top',
                    formatter: function (params) {
                        return params.value !== 0 ? formatCurrency(params.value) : '';
                    },
                    fontSize: 10,
                    fontWeight: 'bold',
                    color: '#000000'
                },
                data: revenueData
            }
        ]
    };

    chart.setOption(option);
    
    const showFranchiseBonus = shouldShowFranchiseBonus;
    updateStats(totalRevenue, totalProfit, avgProfitability, totalFranchiseBonus, showFranchiseBonus);

    const resizeHandler = function () {
        try {
            chart.resize();
        } catch (e) {
            console.warn('Ошибка при изменении размера графика:', e);
        }
    };

    window.addEventListener('resize', resizeHandler);
    chart.resizeHandler = resizeHandler;
}

function updateStats(revenue, profit, profitability, franchiseBonus = 0, showFranchiseBonus = false) {
    const statsInfo = document.getElementById('statsInfo');
    if (!statsInfo) return;
    
    let statsHtml = `
        <div class="stat-item revenue">Выручка: ${formatCurrency(revenue)}</div>
    `;

    if (showFranchiseBonus && franchiseBonus !== 0) {
        statsHtml += `<div class="stat-item bonus">Франшиза сопровождение бонус: ${formatCurrency(franchiseBonus)}</div>`;
    }

    statsHtml += `
        <div class="stat-item ${profit >= 0 ? 'positive' : 'negative'}">Прибыль: ${formatCurrency(profit)}</div>
        <div class="stat-item ${profitability >= 0 ? 'positive' : 'negative'}">Рентабельность: ${profitability.toFixed(1)}%</div>
    `;

    statsInfo.innerHTML = statsHtml;
}

